public class ExponentialBackoffWithJitter {
    private final Random random = new Random();

    public long calculateBackoff(int attempt, long baseMillis, long maxMillis) {
        long exponentialDelay = (long) (baseMillis * Math.pow(2, attempt));
        long cappedDelay = Math.min(maxMillis, exponentialDelay);
        // Full jitter: choose a random value between 0 and the capped exponential delay
        return (long) (random.nextDouble() * cappedDelay);
    }
}
